6	// "From the blog" — the aside block that turns reference pages into
7	// blog on-ramps. Curation is explicit frontmatter (relatedPosts:
8	// [slug, …]) per page; pages without the key render nothing. Compact
9	// rows on purpose: in a 240px column, recognition beats spectacle —
10	// a small banner thumb, the title doing the work, a muted date.
11	const props = withDefaults(
12	  defineProps<{ variant?: 'aside' | 'doc' }>(),
13	  { variant: 'aside' },
14	);
15	
16	const { frontmatter, page } = useData();
17	const route = useRoute();
18	
19	// On a blog post the block lists PEERS — "Related posts". On guide
20	// pages it is an on-ramp from reference into the blog — "From the
21	// blog" says where the reader is being invited.
22	const isBlogPost = computed(
23	  () => /^\/blog\/.+/.test(route.path) && !route.path.endsWith('/blog/'),
24	);
25	const heading = computed(() =>
26	  isBlogPost.value ? 'Related posts' : 'From the blog',
27	);
28	
29	// frontmatter may list any number of slugs, strongest first. The
30	// aside stays capped at three (a calm column, no controls); the doc
31	// grid shows three and expands on demand — a button, not a slider:
32	// hidden-by-carousel content barely gets touched, and post pages
33	// already have one slider (the archive rail).
34	const VISIBLE_COUNT = 3;
35	const expanded = ref(false);
36	
37	const allRelatedPosts = computed(() => {
38	  const slugs: string[] = frontmatter.value.relatedPosts ?? [];
39	  return slugs
40	    .map((slug) => posts.find((post) => post.slug === slug))
41	    .filter((post): post is (typeof posts)[number] => Boolean(post));
42	});
43	
44	const relatedPosts = computed(() => {
45	  if (props.variant === 'aside') return allRelatedPosts.value.slice(0, VISIBLE_COUNT);
46	  if (expanded.value) return allRelatedPosts.value;
47	  return allRelatedPosts.value.slice(0, VISIBLE_COUNT);
48	});
49	
50	const hiddenCount = computed(() =>
51	  props.variant === 'doc' && !expanded.value
52	    ? allRelatedPosts.value.length - VISIBLE_COUNT
53	    : 0,
54	);
55	
56	// a route change collapses the grid again
57	watch(
58	  () => page.value.relativePath,
59	  () => {
60	    expanded.value = false;
61	  },
62	);
63	
64	
65	function formatDate(date: string): string {
66	  return new Date(date + 'T00:00:00Z').toLocaleDateString('en-US', {
67	    month: 'short',
68	    day: 'numeric',
69	    year: 'numeric',
70	    timeZone: 'UTC',
71	  });
72	}
73	</script>
74	
75	<template>
76	  <nav
77	    v-if="relatedPosts.length"
78	    class="related-posts"
79	    :class="`related-posts--${props.variant}`"
80	    aria-label="Related blog posts"
81	  >
82	    <p class="related-posts__heading">{{ heading }}</p>
83	    <a
84	      v-for="post in relatedPosts"
85	      :key="post.slug"
86	      class="related-posts__item"
87	      :href="withBase(post.url)"
88	    >
89	      <img
90	        class="related-posts__thumb"
91	        :src="withBase(post.image)"
92	        :alt="post.title"
93	        width="1200"
94	        height="630"
95	        loading="lazy"
96	      />
97	      <span class="related-posts__body">
98	        <span class="related-posts__title">{{ post.title }}</span>
99	        <span class="related-posts__date">{{ formatDate(post.date) }}</span>
100	      </span>
101	    </a>
102	    <button
103	      v-if="hiddenCount > 0"
104	      type="button"
105	      class="related-posts__more"
106	      @click="expanded = true"
107	    >
108	      {{ isBlogPost ? `More related posts (${hiddenCount})` : `Show ${hiddenCount} more from the blog` }}
109	    </button>
