/* iOS Safari (the only engine matching -webkit-touch-callout): the
   hamburger morph and the menu fade jank on iPhones — open instantly
   instead of animating */
@supports (-webkit-touch-callout: none) {
  .VPNavBarHamburger .container .top,
  .VPNavBarHamburger .container .middle,
  .VPNavBarHamburger .container .bottom,
  .VPNavBarHamburger .container {
    transition: none !important;
  }
  .VPNavScreen,
  .VPNavScreen.fade-enter-active,
  .VPNavScreen.fade-leave-active {
    transition: none !important;
  }
  .VPNavScreen .VPNavScreenMenuGroup .items {
    transition: none !important;
  }
  /* background-clip:text + animated background repaints the glyphs
     every frame on iOS — hold the shine still there (static gradient),
     and the caret's glowing blink goes with it: the hero is fully
     static on iOS */
  .ivh-title .shine,
  .ivh-caret {
    animation: none !important;
  }
}

